    {
        $key = DirectorioExternoPeer::getPrimaryKeyHashFromRow($row, $startcol);
        if (null !== ($obj = DirectorioExternoPeer::getInstanceFromPool($key))) {
            // We no longer rehydrate the object, since this can cause data loss.
