            $cls = DirectorioExternoPeer::OM_CLASS;
            $obj = new $cls();
            $col = $obj->hydrate($row, $startcol);
            DirectorioExternoPeer::addInstanceToPool($obj, $key);
        }

        return array($obj, $col);
    }


