        CiudadPeer::addSelectColumns($criteria);
        $startcol4 = $startcol3 + CiudadPeer::NUM_HYDRATE_COLUMNS;

        EntidadPeer::addSelectColumns($criteria);
        $startcol5 = $startcol4 + EntidadPeer::NUM_HYDRATE_COLUMNS;

        TipoPeticionarioPeer::addSelectColumns($criteria);
        $startcol6 = $startcol5 + TipoPeticionarioPeer::NUM_HYDRATE_COLUMNS;

        $criteria->addJoin(DirectorioExternoPeer::USUARIO_ID, UsuarioPeer::USUARIO_ID, $join_behavior);

        $criteria->addJoin(DirectorioExternoPeer::CIUDAD_ID, CiudadPeer::CIUDAD_ID, $join_behavior);

        $criteria->addJoin(DirectorioExternoPeer::ENTIDAD_ID, EntidadPeer::ENTIDAD_ID, $join_behavior);

        $criteria->addJoin(DirectorioExternoPeer::TIPOPETICIONARIO_ID, TipoPeticionarioPeer::TIPOPETICIONARIO_ID, $join_behavior);

        // symfony_behaviors behavior
        foreach (sfMixer::getCallables(self::getMixerPreSelectHook(__FUNCTION__)) as $sf_hook)
        {
          call_user_func($sf_hook, 'BaseDirectorioExternoPeer', $criteria, $con);
        }


        $stmt = BasePeer::doSelect($criteria, $con);
        $results = array();

        while ($row = $stmt->fetch(PDO::FETCH_NUM)) {
            $key1 = DirectorioExternoPeer::getPrimaryKeyHashFromRow($row, 0);
            if (null !== ($obj1 = DirectorioExternoPeer::getInstanceFromPool($key1))) {
                // We no longer rehydrate the object, since this can cause data loss.
                // See http://www.propelorm.org/ticket/509
                // $obj1->hydrate($row, 0, true); // rehydrate
            } else {
                $cls = DirectorioExternoPeer::getOMClass();

                $obj1 = new $cls();
                $obj1->hydrate($row);
                DirectorioExternoPeer::addInstanceToPool($obj1, $key1);
            } // if obj1 already loaded

                // Add objects for joined Usuario rows

                $key2 = UsuarioPeer::getPrimaryKeyHashFromRow($row, $startcol2);
                if ($key2 !== null) {
                    $obj2 = UsuarioPeer::getInstanceFromPool($key2);
                    if (!$obj2) {
    
                        $cls = UsuarioPeer::getOMClass();

                    $obj2 = new $cls();
                    $obj2->hydrate($row, $startcol2);
                    UsuarioPeer::addInstanceToPool($obj2, $key2);
                } // if $obj2 already loaded

                // Add the $obj1 (DirectorioExterno) to the collection in $obj2 (Usuario)
                $obj2->addDirectorioExterno($obj1);

            } // if joined row is not null

                // Add objects for joined Ciudad rows

                $key3 = CiudadPeer::getPrimaryKeyHashFromRow($row, $startcol3);
                if ($key3 !== null) {
                    $obj3 = CiudadPeer::getInstanceFromPool($key3);
                    if (!$obj3) {
    
                        $cls = CiudadPeer::getOMClass();

                    $obj3 = new $cls();
                    $obj3->hydrate($row, $startcol3);
                    CiudadPeer::addInstanceToPool($obj3, $key3);
                } // if $obj3 already loaded

                // Add the $obj1 (DirectorioExterno) to the collection in $obj3 (Ciudad)
                $obj3->addDirectorioExterno($obj1);

            } // if joined row is not null

                // Add objects for joined Entidad rows

                $key4 = EntidadPeer::getPrimaryKeyHashFromRow($row, $startcol4);
                if ($key4 !== null) {
                    $obj4 = EntidadPeer::getInstanceFromPool($key4);
                    if (!$obj4) {
    
                        $cls = EntidadPeer::getOMClass();

                    $obj4 = new $cls();
                    $obj4->hydrate($row, $startcol4);
                    EntidadPeer::addInstanceToPool($obj4, $key4);
                } // if $obj4 already loaded

                // Add the $obj1 (DirectorioExterno) to the collection in $obj4 (Entidad)
                $obj4->addDirectorioExterno($obj1);

            } // if joined row is not null

                // Add objects for joined TipoPeticionario rows

                $key5 = TipoPeticionarioPeer::getPrimaryKeyHashFromRow($row, $startcol5);
                if ($key5 !== null) {
                    $obj5 = TipoPeticionarioPeer::getInstanceFromPool($key5);
                    if (!$obj5) {
    
                        $cls = TipoPeticionarioPeer::getOMClass();

                    $obj5 = new $cls();
                    $obj5->hydrate($row, $startcol5);
                    TipoPeticionarioPeer::addInstanceToPool($obj5, $key5);
                } // if $obj5 already loaded

                // Add the $obj1 (DirectorioExterno) to the collection in $obj5 (TipoPeticionario)
                $obj5->addDirectorioExterno($obj1);

            } // if joined row is not null

            $results[] = $obj1;
        }
        $stmt->closeCursor();

        return $results;
    }

