     * @param      PropelPDO $con the connection to use
     * @return DirectorioExterno
     */
    public static function retrieveByPK($pk, PropelPDO $con = null)
    {

        if (null !== ($obj = DirectorioExternoPeer::getInstanceFromPool((string) $pk))) {
            return $obj;
        }

        if ($con === null) {
            $con = Propel::getConnection(DirectorioExternoPeer::DATABASE_NAME, Propel::CONNECTION_READ);
        }

        $criteria = new Criteria(DirectorioExternoPeer::DATABASE_NAME);
        $criteria->add(DirectorioExternoPeer::DIRECTORIOEXTERNO_ID, $pk);

        $v = DirectorioExternoPeer::doSelect($criteria, $con);

        return !empty($v) > 0 ? $v[0] : null;
    }

