    public static function retrieveByPKs($pks, PropelPDO $con = null)
    {
        if ($con === null) {
            $con = Propel::getConnection(DirectorioExternoPeer::DATABASE_NAME, Propel::CONNECTION_READ);
        }

        $objs = null;
        if (empty($pks)) {
            $objs = array();
        } else {
            $criteria = new Criteria(DirectorioExternoPeer::DATABASE_NAME);
            $criteria->add(DirectorioExternoPeer::DIRECTORIOEXTERNO_ID, $pks, Criteria::IN);
            $objs = DirectorioExternoPeer::doSelect($criteria, $con);
        }

        return $objs;
    }

